# IMPOSSIBLE: Turn off the light in the study room (no device listed)

tree = py_trees.composites.Parallel(
    name="HomeAutomationTasks",
    policy=py_trees.common.ParallelPolicy.SuccessOnAll(),
    children=[
        py_trees.composites.Sequence(
            name="GuestBedroomDehumidifier",
            memory=True,
            children=[
                py_trees.composites.Selector(
                    name="EnsureDehumidifierOn",
                    memory=False,
                    children=[
                        PropertyConditionNode(
                            name="IsOn",
                            property_url="http://localhost:8080/workspaces/home86/guest_bedroom/artifacts/guestBedroomDehumidifiers/properties/state",
                            expected_value="on"
                        ),
                        ActionAffordanceNode(
                            name="TurnOn",
                            action_url="http://localhost:8080/workspaces/home86/guest_bedroom/artifacts/guestBedroomDehumidifiers/turn_on"
                        )
                    ]
                ),
                ActionAffordanceNode(
                    name="SetIntensity",
                    action_url="http://localhost:8080/workspaces/home86/guest_bedroom/artifacts/guestBedroomDehumidifiers/set_intensity",
                    parameters={"intensity": 90}
                )
            ]
        ),
        py_trees.composites.Sequence(
            name="BalconyLight",
            memory=True,
            children=[
                py_trees.composites.Selector(
                    name="EnsureLightOn",
                    memory=False,
                    children=[
                        PropertyConditionNode(
                            name="IsOn",
                            property_url="http://localhost:8080/workspaces/home86/balcony/artifacts/balconyLight/properties/state",
                            expected_value="on"
                        ),
                        ActionAffordanceNode(
                            name="TurnOn",
                            action_url="http://localhost:8080/workspaces/home86/balcony/artifacts/balconyLight/turn_on"
                        )
                    ]
                ),
                ActionAffordanceNode(
                    name="SetBrightness",
                    action_url="http://localhost:8080/workspaces/home86/balcony/artifacts/balconyLight/set_brightness",
                    parameters={"brightness": 40}
                )
            ]
        ),
        py_trees.composites.Sequence(
            name="DiningRoomDehumidifier",
            memory=True,
            children=[
                py_trees.composites.Selector(
                    name="EnsureDehumidifierOn",
                    memory=False,
                    children=[
                        PropertyConditionNode(
                            name="IsOn",
                            property_url="http://localhost:8080/workspaces/home86/ding_room/artifacts/dingRoomDehumidifiers/properties/state",
                            expected_value="on"
                        ),
                        ActionAffordanceNode(
                            name="TurnOn",
                            action_url="http://localhost:8080/workspaces/home86/ding_room/artifacts/dingRoomDehumidifiers/turn_on"
                        )
                    ]
                ),
                ActionAffordanceNode(
                    name="SetModeAuto",
                    action_url="http://localhost:8080/workspaces/home86/ding_room/artifacts/dingRoomDehumidifiers/set_mode",
                    parameters={"mode": "auto"}
                )
            ]
        ),
        py_trees.composites.Sequence(
            name="LivingRoomCurtain",
            memory=True,
            children=[
                ActionAffordanceNode(
                    name="SetDegree",
                    action_url="http://localhost:8080/workspaces/home86/living_room/artifacts/livingRoomCurtain/set_degree",
                    parameters={"degree": 20}
                )
            ]
        )
    ]
)
